def countColorings(n, edges, k):
    adj = [0] * n
    for u, v in edges:
        adj[u] |= 1 << v
        adj[v] |= 1 << u
    groups = []

    def go(v):
        if v == n:
            return 1
        total = 0
        for g in range(len(groups)):
            if groups[g] & adj[v] == 0:
                groups[g] |= 1 << v
                total += go(v + 1)
                groups[g] ^= 1 << v
        if len(groups) < k:
            groups.append(1 << v)
            total += go(v + 1)
            groups.pop()
        return total

    return go(0)
